INSERT INTO public.content_block (id, section, key, value, updated_at) VALUES
  (gen_random_uuid(), 'settings', 'main', '{"provisional": true, "clientAccess": "proximamente", "privacyPolicyVersion": "provisoria-0"}'::jsonb, now()),
  (gen_random_uuid(), 'brand', 'main', '{"name": "PRIVAT"}'::jsonb, now()),
  (gen_random_uuid(), 'seo', 'main', '{"title": "Gestión y administración de propiedades en Uruguay", "description": "Administramos, supervisamos y conservamos propiedades en Maldonado, Punta del Este y zonas seleccionadas de Uruguay. Gestión documentada, estés donde estés."}'::jsonb, now()),
  (gen_random_uuid(), 'nav', 'main', '{"items": [{"label": "Servicios", "href": "#servicios"}, {"label": "Bitácora", "href": "#bitacora"}, {"label": "Cómo trabajamos", "href": "#transparencia"}, {"label": "Cobertura", "href": "#cobertura"}, {"label": "Cotizador", "href": "#cotizador"}, {"label": "Preguntas", "href": "#preguntas"}, {"label": "Contacto", "href": "#contacto"}]}'::jsonb, now()),
  (gen_random_uuid(), 'hero', 'main', '{"title": "Gestión integral y conservación patrimonial de propiedades en Uruguay", "subtitle": "Administramos, supervisamos y conservamos propiedades para que sus propietarios tengan tranquilidad, control y respaldo, estén donde estén.", "complement": "Nos ocupamos de la administración, el mantenimiento y la supervisión de tu propiedad. Coordinamos profesionales, controlamos gastos y documentamos cada actuación para que tengas información clara y tranquilidad en todo momento.", "cta": "Solicitar una propuesta", "secondaryCta": "Calcular mi abono", "slogan": "Tu propiedad, nuestro compromiso.", "badges": ["Gestión profesional y documentada", "Para propietarios en Uruguay y en el exterior"], "image": "casa-frente-mar"}'::jsonb, now()),
  (gen_random_uuid(), 'services', 'main', '{"eyebrow": "Servicios", "title": "Tres niveles de contratación, según lo que necesita tu propiedad", "intro": "Niveles simples y comparables, que se completan con servicios complementarios. Cada propuesta se adapta a las necesidades de tu propiedad."}'::jsonb, now()),
  (gen_random_uuid(), 'transparency', 'main', '{"eyebrow": "Cómo trabajamos", "title": "Transparencia operativa", "items": [{"title": "Cuentas claras", "text": "Los fondos de tu propiedad se manejan separados de nuestros honorarios, con registro y rendición de cada movimiento."}, {"title": "Límites de gasto", "text": "Definimos contigo, por escrito, el monto que podemos gastar sin consulta previa. Por encima de ese límite, siempre pedimos tu aprobación. Ante una urgencia que ponga en riesgo personas o el patrimonio, actuamos para contener el daño y te informamos a la mayor brevedad."}, {"title": "Informes periódicos", "text": "Recibes informes con fotografías, gastos y comprobantes, con la frecuencia acordada en tu contrato."}, {"title": "Registro documental", "text": "Visitas, incidencias, intervenciones y situaciones relevantes quedan documentadas, con fecha, responsable y evidencias."}]}'::jsonb, now()),
  (gen_random_uuid(), 'coverage', 'main', '{"eyebrow": "Cobertura", "title": "Gestión de propiedades en Maldonado, Punta del Este y zonas seleccionadas de Uruguay", "text": "Nuestra operación se concentra en Maldonado y Punta del Este, con posibilidad de atender otras localidades según las características del inmueble y el alcance del servicio. Toca el mapa donde está tu propiedad para ver la distancia aproximada desde nuestra base.", "viaticoNote": "La distancia es una estimación: línea recta corregida por un factor de ruta. El valor definitivo se confirma en la propuesta personalizada."}'::jsonb, now()),
  (gen_random_uuid(), 'quoter', 'main', '{"eyebrow": "Cotizador", "title": "Calcula una estimación preliminar de tu abono", "intro": "Tres pasos: tipo de propiedad, nivel de servicio y ubicación.", "disclaimer": "Estimación preliminar en dólares, sin IVA. No es una cotización definitiva: el valor final se confirma en una propuesta personalizada.", "cta": "Solicitar propuesta personalizada"}'::jsonb, now()),
  (gen_random_uuid(), 'contact', 'main', '{"eyebrow": "Contacto", "title": "Solicita una propuesta", "text": "Cuéntanos sobre tu propiedad y tus necesidades. Evaluamos el caso, coordinamos una instancia de intercambio y te preparamos una propuesta de servicios a medida.", "phone": null, "whatsapp": null, "email": null, "address": null}'::jsonb, now()),
  (gen_random_uuid(), 'footer', 'main', '{"legal": null, "privacyPolicyUrl": null, "termsUrl": null}'::jsonb, now())
ON CONFLICT (section, key) DO NOTHING;

-- ============================================================================
-- Etapa F1 (11/11/2026): FAQ, secciones nuevas y actualización de textos.
-- Idempotente y sin pisar ediciones del panel (ver comentarios de cada bloque).
-- ============================================================================
-- FAQ del cliente (7 categorías). Solo en la primera ejecución: antes de crear 'faqsection'.
INSERT INTO public.faq (id, category, question, answer, sort_order, visible)
SELECT gen_random_uuid(), v.category, v.question, v.answer, v.sort_order, true FROM (VALUES
  ('Sobre PRIVAT y sus servicios', '¿Qué es PRIVAT y a qué se dedica?', 'PRIVAT es una empresa especializada en la gestión y administración de propiedades. Nos ocupamos de coordinar, supervisar y gestionar las necesidades de cada inmueble, procurando conservar su valor, optimizar su funcionamiento y brindar tranquilidad a sus propietarios.', 110),
  ('Sobre PRIVAT y sus servicios', '¿Qué tipo de propiedades administra PRIVAT?', 'Trabajamos con apartamentos, casas, residencias, propiedades de temporada y otros inmuebles. Adaptamos nuestros servicios a las características y necesidades particulares de cada propiedad.', 120),
  ('Sobre PRIVAT y sus servicios', '¿PRIVAT trabaja únicamente en Punta del Este?', 'Nuestra área de actuación está centrada en Maldonado y Punta del Este, aunque podemos evaluar solicitudes de otras localidades de Uruguay según las características del inmueble y el servicio requerido.', 130),
  ('Sobre PRIVAT y sus servicios', '¿Qué diferencia a PRIVAT de una inmobiliaria tradicional?', 'Nuestro enfoque está orientado a la gestión y conservación de propiedades. No nos limitamos a una operación inmobiliaria: buscamos establecer una relación continua con el propietario, ocupándonos de los aspectos operativos, administrativos y de mantenimiento de su inmueble.', 140),
  ('Administración y gestión', '¿Qué servicios puedo contratar?', 'Ofrecemos diferentes servicios que pueden contratarse individualmente o mediante una propuesta integral. Entre ellos:
• Administración y seguimiento de gastos.
• Control de facturas y vencimientos.
• Inspecciones periódicas del inmueble.
• Supervisión del estado general de la propiedad.
• Coordinación de mantenimiento y reparaciones.
• Gestión de proveedores y servicios técnicos.
• Limpieza y acondicionamiento.
• Mantenimiento de jardines y piscinas.
• Atención y coordinación ante imprevistos.
• Gestión integral de propiedades destinadas al uso de terceros durante la temporada alta en Punta del Este.
• Preparación de la propiedad para la llegada de sus propietarios.
Cada propuesta se adapta a las necesidades de la propiedad.', 210),
  ('Administración y gestión', '¿Tengo que contratar todos los servicios?', 'No. Cada propietario puede seleccionar los servicios que necesita. Elaboramos una propuesta personalizada, evitando contratar prestaciones que no resulten necesarias para su inmueble.', 220),
  ('Administración y gestión', '¿Puedo contratar solamente el mantenimiento de mi propiedad?', 'Sí. Es posible solicitar servicios específicos, como inspecciones, mantenimiento preventivo, coordinación de reparaciones o acondicionamiento de la propiedad.', 230),
  ('Administración y gestión', '¿PRIVAT realiza inspecciones cuando no estoy en Uruguay?', 'Sí. Uno de nuestros servicios consiste en establecer un cronograma de visitas para verificar el estado general del inmueble, identificar posibles inconvenientes y comunicar cualquier situación que requiera atención.
Además, contamos con una iniciativa denominada Puertas Abiertas: según la frecuencia acordada con el cliente, abrimos las aberturas de la propiedad durante una visita programada para favorecer la circulación de aire. Esta práctica contribuye a renovar el ambiente interior, regular la humedad y reducir los olores característicos de los espacios que permanecen cerrados durante períodos prolongados.', 240),
  ('Administración y gestión', '¿Puedo recibir fotografías o informes sobre el estado de mi propiedad?', 'Sí. Proporcionamos informes periódicos acompañados de fotografías y observaciones relevantes, de acuerdo con la modalidad de servicio contratada. También podemos generar informes adicionales cuando el propietario lo necesite.', 250),
  ('Propietarios en el exterior', 'Vivo fuera de Uruguay. ¿Puedo contratar PRIVAT igualmente?', 'Por supuesto. Uno de nuestros enfoques principales es brindar soluciones a propietarios que residen fuera de Uruguay y necesitan contar con un referente local de confianza para gestionar sus propiedades.', 310),
  ('Propietarios en el exterior', '¿Cómo puedo mantenerme informado sobre mi propiedad desde otro país?', 'Mantenemos comunicación directa con nuestros clientes, dondequiera que se encuentren, y proporcionamos información sobre las gestiones realizadas, gastos, mantenimiento e incidencias relevantes. Próximamente, los clientes contarán además con una bitácora digital de su propiedad o propiedades, con el historial de gestión actualizado. Mantenemos canales de comunicación abiertos para atender consultas y coordinar situaciones que requieran seguimiento.', 320),
  ('Propietarios en el exterior', '¿Puedo autorizar a PRIVAT para que gestione pagos y gastos de mi propiedad?', 'Sí. Podemos coordinar el seguimiento y la gestión administrativa de facturas, servicios y gastos asociados al inmueble. Los procedimientos de autorización, disponibilidad de fondos y rendición se establecen previamente con cada propietario.', 330),
  ('Propietarios en el exterior', '¿Qué sucede si surge un problema mientras estoy fuera del país?', 'Actuamos como referente local para identificar la situación, evaluar las alternativas y coordinar su resolución. Cuando sea necesario, nos comunicamos con el propietario para solicitar autorización antes de realizar trabajos o asumir gastos extraordinarios.', 340),
  ('Mantenimiento y reparaciones', '¿PRIVAT se encarga de coordinar reparaciones?', 'Sí. Coordinamos la intervención de proveedores y técnicos especializados para atender las necesidades de mantenimiento y reparación de la propiedad.', 410),
  ('Mantenimiento y reparaciones', '¿Cómo se seleccionan los proveedores?', 'Trabajamos con proveedores y profesionales seleccionados según el tipo de servicio requerido, considerando su experiencia y trayectoria, y priorizando la calidad del trabajo, la confiabilidad y una adecuada relación entre costo y resultado.', 420),
  ('Mantenimiento y reparaciones', '¿Puedo solicitar presupuestos antes de realizar una reparación?', 'Sí. Cuando una intervención requiere autorización o representa un gasto extraordinario, podemos gestionar presupuestos para que el propietario evalúe y apruebe la propuesta antes de avanzar.', 430),
  ('Mantenimiento y reparaciones', '¿Qué sucede ante una emergencia?', 'Ante una situación urgente, PRIVAT coordina las acciones necesarias para procurar proteger la propiedad y reducir posibles daños. Los alcances de actuación y las autorizaciones correspondientes se establecen previamente en el contrato de servicio.', 440),
  ('Costos y contratación', '¿Cuánto cuesta contratar PRIVAT?', 'El costo depende de las características de la propiedad, su ubicación, los servicios solicitados y la frecuencia de atención requerida. Elaboramos propuestas personalizadas para que cada propietario conozca claramente el alcance del servicio y sus honorarios.', 510),
  ('Costos y contratación', '¿Los gastos de mantenimiento están incluidos en el servicio?', 'No necesariamente. Los honorarios de administración y gestión se diferencian de los gastos propios de la propiedad, como reparaciones, materiales, servicios públicos, proveedores y mantenimiento. Estos gastos son responsabilidad del propietario y se gestionan según las condiciones acordadas.', 520),
  ('Costos y contratación', '¿PRIVAT adelanta dinero para pagar gastos de la propiedad?', 'No. Los fondos necesarios para cubrir los gastos corresponden al propietario. PRIVAT puede encargarse de su coordinación, seguimiento y rendición, conforme a las condiciones establecidas.', 530),
  ('Costos y contratación', '¿Existe un contrato de prestación de servicios?', 'Sí. Formalizamos la relación mediante un contrato donde se especifican los servicios contratados, responsabilidades, honorarios, condiciones de funcionamiento y demás aspectos relevantes.', 540),
  ('Costos y contratación', '¿Puedo modificar los servicios contratados posteriormente?', 'Sí. Las necesidades de una propiedad pueden cambiar con el tiempo. Es posible revisar y ajustar el alcance de los servicios mediante un acuerdo entre ambas partes.', 550),
  ('Costos y contratación', '¿Existe un plazo mínimo de contratación?', 'PRIVAT no establece un plazo mínimo de contratación. Las condiciones de permanencia y finalización del servicio se detallan en la propuesta y el contrato correspondiente.', 560),
  ('Confianza y seguridad', '¿Cómo puedo saber que mi propiedad está siendo correctamente atendida?', 'Trabajamos con seguimiento de las tareas, comunicación directa e información sobre las gestiones realizadas. Nuestro objetivo es que el propietario tenga conocimiento y control sobre lo que sucede con su inmueble.', 610),
  ('Confianza y seguridad', '¿PRIVAT puede tomar decisiones sobre mi propiedad sin consultarme?', 'Las decisiones se toman respetando las facultades y autorizaciones establecidas en el contrato. Las intervenciones extraordinarias y los gastos que requieran aprobación se comunican previamente al propietario, salvo las actuaciones urgentes que hayan sido expresamente autorizadas o situaciones de fuerza mayor —como desastres naturales— que requieran una actuación inmediata para proteger o salvaguardar el patrimonio del cliente.', 620),
  ('Confianza y seguridad', '¿PRIVAT se responsabiliza por los trabajos realizados por terceros?', 'PRIVAT coordina y supervisa las intervenciones dentro del alcance del servicio contratado. La ejecución técnica y las garantías de los trabajos corresponden a los proveedores o profesionales responsables, según las condiciones de cada contratación.', 630),
  ('Confianza y seguridad', '¿Cómo puedo comenzar a trabajar con PRIVAT?', 'El primer paso es contactarnos y compartir algunos datos de tu propiedad y tus necesidades. Evaluaremos el caso, coordinaremos una instancia de intercambio y prepararemos una propuesta de servicios adaptada a tus requerimientos.', 640),
  ('Plataforma y seguimiento digital', '¿Puedo consultar la información de mi propiedad desde una plataforma online?', 'Estamos preparando una bitácora digital para que cada cliente pueda consultar la información de gestión de su propiedad, de acuerdo con las funcionalidades habilitadas y el servicio contratado. Estará disponible próximamente.', 710),
  ('Plataforma y seguimiento digital', '¿Puedo acceder a facturas, comprobantes y documentos de mi propiedad?', 'Sí. Cuando el espacio de clientes esté disponible, la documentación digital asociada a la gestión podrá consultarse allí una vez cargada en la plataforma. Mientras tanto, la compartimos con los informes y rendiciones.', 720),
  ('Plataforma y seguimiento digital', '¿Puedo consultar el historial de mantenimiento de mi propiedad?', 'Sí. Registramos las gestiones e intervenciones realizadas, lo que facilita el seguimiento de trabajos, incidencias y tareas de mantenimiento. La consulta en línea de ese historial estará disponible con el espacio de clientes.', 730),
  ('Plataforma y seguimiento digital', '¿Puedo contratar PRIVAT para administrar más de una propiedad?', 'Sí. Podemos gestionar varias propiedades de un mismo titular. La propuesta se adapta a la cantidad de inmuebles, sus ubicaciones y las necesidades de administración de cada uno.', 740),
  ('Plataforma y seguimiento digital', '¿Los informes quedan disponibles para consultarlos más adelante?', 'Los informes y registros digitales que se generen y carguen en la plataforma podrán consultarse posteriormente, de acuerdo con las funcionalidades habilitadas y las condiciones del servicio contratado.', 750)
) AS v(category, question, answer, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM public.content_block WHERE section = 'faqsection' AND key = 'main');

-- Etapa F1: secciones nuevas (solo si no existen)
INSERT INTO public.content_block (id, section, key, value, updated_at) VALUES
  (gen_random_uuid(), 'complementary', 'main', '{"eyebrow": "Servicios complementarios", "title": "Prestaciones que se suman a cualquier nivel", "intro": "Se contratan por separado, con alcance, responsables y presupuesto acordados previamente.", "items": [{"title": "Puertas Abiertas", "text": "Visitas programadas para ventilar y renovar el aire de la propiedad, con la frecuencia acordada y según el clima, la seguridad y el estado del inmueble. No reemplaza un diagnóstico técnico de humedad.", "image": "living-hogar"}, {"title": "Preparación de llegadas", "text": "Acondicionamiento de la propiedad y coordinación de servicios antes de que llegues.", "image": "cocina-parrillero"}, {"title": "Gestión de temporada alta", "text": "Administración de la propiedad durante su uso por terceros en temporada alta, con un alcance definido en un acuerdo específico.", "image": "penthouse-terraza"}, {"title": "Mantenimiento y proveedores", "text": "Coordinación de mantenimiento preventivo y correctivo, y de proveedores especializados, dentro del alcance contratado.", "image": "inspeccion-tablero"}, {"title": "Espacios exteriores", "text": "Coordinación de piscina, jardinería, limpieza y áreas complementarias.", "image": "casa-piedra-campo"}, {"title": "Obras y reformas", "text": "Coordinación y seguimiento de obras y reformas, con presupuesto, alcance y responsables expresamente acordados.", "image": "inspeccion-exterior-tablet"}], "note": "Los servicios complementarios se presupuestan por separado."}'::jsonb, now()),
  (gen_random_uuid(), 'bitacora', 'main', '{"eyebrow": "Gestión digital", "title": "Cada propiedad tiene su propio historial. Cada actuación queda registrada.", "text": "En PRIVAT creemos que una gestión transparente necesita información documentada. Por eso, cada propiedad contará con una bitácora digital donde registramos incidencias, visitas, intervenciones, observaciones y situaciones relevantes, con fecha, responsable y evidencias.", "items": [{"title": "Visitas e inspecciones", "text": "Fecha, motivo, observaciones y resultados."}, {"title": "Incidencias", "text": "Desperfectos, anomalías, daños y situaciones imprevistas."}, {"title": "Mantenimiento", "text": "Trabajos realizados, intervenciones y recomendaciones."}, {"title": "Proveedores", "text": "Visitas, diagnósticos, presupuestos y trabajos ejecutados."}, {"title": "Comunicaciones y documentos", "text": "Autorizaciones, fotografías, documentos y comprobantes."}], "note": "Próximamente: acceso de clientes a la plataforma para consultar el historial actualizado de su propiedad desde cualquier lugar.", "image": "inspeccion-cocina"}'::jsonb, now()),
  (gen_random_uuid(), 'faqsection', 'main', '{"eyebrow": "Preguntas frecuentes", "title": "Preguntas frecuentes", "intro": "Las dudas habituales de quienes evalúan confiarnos la gestión de su propiedad.", "closingTitle": "¿Tenés otra consulta?", "closingText": "Cada propiedad tiene necesidades particulares. Si no encontraste la respuesta que buscabas, nuestro equipo está disponible para asesorarte y ayudarte a encontrar la solución adecuada.", "closingCta": "Contactar"}'::jsonb, now())
ON CONFLICT (section, key) DO NOTHING;

-- Etapa F1: textos del cliente. Se reemplaza la sección SOLO si sigue exactamente igual al
