UPDATE public.content_block SET value = '{"title": "Gestión y administración de propiedades en Uruguay", "description": "Administramos, supervisamos y conservamos propiedades en Maldonado, Punta del Este y zonas seleccionadas de Uruguay. Gestión documentada, estés donde estés."}'::jsonb, updated_at = now()
  WHERE section = 'seo' AND key = 'main' AND value = '{"title": "Property Management técnico en Maldonado, Punta del Este y Rocha", "description": "Administración patrimonial transparente con supervisión de arquitectos: cuentas separadas, fondo rotativo, informes mensuales y mantenimiento preventivo."}'::jsonb;
UPDATE public.content_block SET value = '{"items": [{"label": "Servicios", "href": "#servicios"}, {"label": "Bitácora", "href": "#bitacora"}, {"label": "Cómo trabajamos", "href": "#transparencia"}, {"label": "Cobertura", "href": "#cobertura"}, {"label": "Cotizador", "href": "#cotizador"}, {"label": "Preguntas", "href": "#preguntas"}, {"label": "Contacto", "href": "#contacto"}]}'::jsonb, updated_at = now()
  WHERE section = 'nav' AND key = 'main' AND value = '{"items": [{"label": "Servicios", "href": "#servicios"}, {"label": "Transparencia", "href": "#transparencia"}, {"label": "Cobertura", "href": "#cobertura"}, {"label": "Cotizador", "href": "#cotizador"}, {"label": "Contacto", "href": "#contacto"}]}'::jsonb;
UPDATE public.content_block SET value = '{"title": "Gestión integral y conservación patrimonial de propiedades en Uruguay", "subtitle": "Administramos, supervisamos y conservamos propiedades para que sus propietarios tengan tranquilidad, control y respaldo, estén donde estén.", "complement": "Nos ocupamos de la administración, el mantenimiento y la supervisión de tu propiedad. Coordinamos profesionales, controlamos gastos y documentamos cada actuación para que tengas información clara y tranquilidad en todo momento.", "cta": "Solicitar una propuesta", "secondaryCta": "Calcular mi abono", "slogan": "Tu propiedad, nuestro compromiso.", "badges": ["Gestión profesional y documentada", "Para propietarios en Uruguay y en el exterior"], "image": "casa-frente-mar"}'::jsonb, updated_at = now()
  WHERE section = 'hero' AND key = 'main' AND value = '{"title": "Gestión patrimonial inteligente y rigor técnico para tu propiedad en el Este", "subtitle": "Olvídate de la operativa diaria. Combinamos administración contable transparente, control de proveedores y supervisión de arquitectura en Maldonado, Punta del Este y Rocha.", "cta": "Solicitar diagnóstico", "badges": ["Supervisión directa por arquitectos", "Cuentas bancarias separadas y fondo rotativo"]}'::jsonb;
UPDATE public.content_block SET value = '{"eyebrow": "Servicios", "title": "Tres niveles de contratación, según lo que necesita tu propiedad", "intro": "Niveles simples y comparables, que se completan con servicios complementarios. Cada propuesta se adapta a las necesidades de tu propiedad."}'::jsonb, updated_at = now()
  WHERE section = 'services' AND key = 'main' AND value = '{"eyebrow": "Servicios", "title": "Tres niveles de servicio, según lo que necesita tu propiedad", "intro": "No solo pagamos facturas: auditamos, planificamos el mantenimiento y te rendimos cuentas con fotos y números."}'::jsonb;
UPDATE public.content_block SET value = '{"eyebrow": "Cómo trabajamos", "title": "Transparencia operativa", "items": [{"title": "Cuentas claras", "text": "Los fondos de tu propiedad se manejan separados de nuestros honorarios, con registro y rendición de cada movimiento."}, {"title": "Límites de gasto", "text": "Definimos contigo, por escrito, el monto que podemos gastar sin consulta previa. Por encima de ese límite, siempre pedimos tu aprobación. Ante una urgencia que ponga en riesgo personas o el patrimonio, actuamos para contener el daño y te informamos a la mayor brevedad."}, {"title": "Informes periódicos", "text": "Recibes informes con fotografías, gastos y comprobantes, con la frecuencia acordada en tu contrato."}, {"title": "Registro documental", "text": "Visitas, incidencias, intervenciones y situaciones relevantes quedan documentadas, con fecha, responsable y evidencias."}]}'::jsonb, updated_at = now()
  WHERE section = 'transparency' AND key = 'main' AND value = '{"eyebrow": "Cómo trabajamos", "title": "Transparencia operativa", "items": [{"title": "Cuentas claras", "text": "Operamos con cuentas bancarias separadas y un fondo rotativo con reposición mensual. Tu dinero nunca se mezcla con el de la empresa."}, {"title": "Límites de gasto", "text": "Política clara por escrito: definimos contigo el monto que podemos gastar sin consulta previa. Por encima de ese límite, siempre pedimos tu aprobación."}, {"title": "Informe mensual", "text": "Cada mes recibes el reporte fotográfico de la propiedad, el estado financiero y la evolución de consumos para detectar pérdidas o consumos anómalos."}]}'::jsonb;
UPDATE public.content_block SET value = '{"eyebrow": "Cobertura", "title": "Gestión de propiedades en Maldonado, Punta del Este y zonas seleccionadas de Uruguay", "text": "Nuestra operación se concentra en Maldonado y Punta del Este, con posibilidad de atender otras localidades según las características del inmueble y el alcance del servicio. Toca el mapa donde está tu propiedad para ver la distancia aproximada desde nuestra base.", "viaticoNote": "La distancia es una estimación: línea recta corregida por un factor de ruta. El valor definitivo se confirma en la propuesta personalizada."}'::jsonb, updated_at = now()
  WHERE section = 'coverage' AND key = 'main' AND value = '{"eyebrow": "Cobertura", "title": "Trabajamos en todo Uruguay", "text": "Toca el mapa donde está tu propiedad y te mostramos la distancia aproximada desde nuestra base y el viático de traslado.", "viaticoNote": "La distancia es una estimación: línea recta corregida por un factor de ruta. El valor definitivo se confirma en la auditoría inicial."}'::jsonb;
UPDATE public.content_block SET value = '{"eyebrow": "Cotizador", "title": "Calcula una estimación preliminar de tu abono", "intro": "Tres pasos: tipo de propiedad, nivel de servicio y ubicación.", "disclaimer": "Estimación preliminar en dólares, sin IVA. No es una cotización definitiva: el valor final se confirma en una propuesta personalizada.", "cta": "Solicitar propuesta personalizada"}'::jsonb, updated_at = now()
  WHERE section = 'quoter' AND key = 'main' AND value = '{"eyebrow": "Cotizador", "title": "Conoce una estimación de tu abono", "intro": "Tres pasos: tipo de propiedad, nivel de servicio y ubicación.", "disclaimer": "Estimación orientativa sujeta a auditoría inicial.", "cta": "Congela esta tarifa programando una auditoría inicial"}'::jsonb;
UPDATE public.content_block SET value = '{"eyebrow": "Contacto", "title": "Solicita una propuesta", "text": "Cuéntanos sobre tu propiedad y tus necesidades. Evaluamos el caso, coordinamos una instancia de intercambio y te preparamos una propuesta de servicios a medida.", "phone": null, "whatsapp": null, "email": null, "address": null}'::jsonb, updated_at = now()
  WHERE section = 'contact' AND key = 'main' AND value = '{"eyebrow": "Contacto", "title": "Solicita un diagnóstico inicial", "text": "Cuéntanos sobre tu propiedad y te contactamos para coordinar la auditoría.", "phone": null, "whatsapp": null, "email": null, "address": null}'::jsonb;
